style.css:
/* Obsidian Luxe — Global */
 /* i really want this to be global */

/* swap these values to change the palette */
:root {
  --my-bg: #101114;
  --my-surface: #191a1f;
  --my-surface-hover: #222329;
  --my-text: #e8e4dc;
  --my-muted: #a19b90;
  --my-gold: #c6a66b;
  --my-border: #343239;
}

/* dark backgrounds */
html, body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* elegant typography */
body {
  font-family: "Segoe UI", "Georgia", sans-serif !important;
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-gold) !important;
  text-decoration-color: transparent !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: #ead2a0 !important;
  text-decoration-color: currentColor !important;
}

/* refined form elements */
input, textarea, select {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 9px !important;
}

/* buttons */
button {
  border-radius: 8px !important;
  transition: background 0.2s ease, border-color 0.2s ease !important;
}

/* images */
img {
  border-radius: 5px !important;
}

/* subtle selection */
::selection {
  background: var(--my-gold) !important;
  color: #101114 !important;
}

/* elegant scrollbars */
* {
  scrollbar-color: #766344 var(--my-bg) !important;
  scrollbar-width: thin !important;
}
